// Vendor Dashboard V3: static governance checks require no secrets or database.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const read = relative => fs.readFileSync(path.join(root,relative),"utf8");
const nav = read("components/admin/adminConfig.ts");
const page = read("app/admin/vendor-approvals/page.tsx");
const queue = read("components/admin/vendor-approvals/VendorApprovalQueue.tsx");
const dashboard = read("app/admin/dashboard/page.tsx");
const vendors = read("components/admin/sections/VendorsSection.tsx");
const service = read("services/vendorProfileChangeService.ts");
const migration = read("ops/vendor-approval/pending/20261013133000_vendor_profile_approval_atomic.sql");
const actions = read("app/actions.ts");
let count=0;
function check(name,ok){if(!ok)throw new Error("V3_ADMIN_APPROVAL_FAIL:"+name);console.log("PASS",name);count++;}
check("admin nav destination",nav.includes('/admin/vendor-approvals')&&nav.includes('key: "vendor-approvals"'));
check("navigation command group",nav.includes('"vendor-approvals", "vendor-crm"'));
check("server page Superadmin-only",page.includes("session.isSuperadmin")&&page.includes('redirect("/admin/login?error=unauthorized")'));
check("server queue fetch",page.includes("listPendingVendorProfileChangeRequests()"));
check("bounded oldest-first",service.includes('.order("created_at", { ascending: true })\n      .limit(100)'));
check("dashboard pending count",dashboard.includes("countPendingVendorProfileChangeRequests()"));
check("vendor directory link",vendors.includes('href="/admin/vendor-approvals"'));
check("request-old-new diff",queue.includes("Approved</th>")&&queue.includes("Requested</th>"));
check("office approval disabled",queue.includes("office || fields.length === 0"));
check("rejection requires reason",queue.includes('if (!approve && !note)'));
check("client calls existing server actions",queue.includes("adminApproveVendorProfileChangeRequest(req.id,note)")&&queue.includes("adminRejectVendorProfileChangeRequest(req.id,note)"));
check("admin server actor",actions.includes("const user = await requireSuperadmin()"));
check("atomic RPC used",service.includes('db.rpc("qf_approve_vendor_profile_update_v3"'));
check("RPC never falls back to split vendor updates",service.includes("No missing-RPC fallback."));
check("office atomic gate default deny",service.includes('QF_VENDOR_OFFICE_ATOMIC_APPROVAL_CERTIFIED !== "1"'));
check("admin review revalidation",actions.includes('revalidatePath("/admin/vendor-approvals")'));
check("new pending uniqueness",migration.includes("uq_vendor_pending_review_kind_v3"));
check("authenticated raw INSERT revoked",migration.includes("revoke insert on public.vendor_profile_change_requests from authenticated"));
check("atomic request and vendor locks",migration.includes("where id = p_request_id for update")&&migration.includes("where v.id = r.vendor_id for update"));
check("stale snapshot CAS",migration.includes("QF_VENDOR_REVIEW_STALE"));
check("forbid unreviewed fields",migration.includes("QF_VENDOR_REVIEW_UNEXPECTED_FIELD"));
check("reject financial override",!migration.includes("remaining_credits ="));
check("RPC restricted to service role",migration.includes("to service_role;")&&migration.includes("from public, anon, authenticated"));
check("append-only audit table",migration.includes("vendor_change_review_audit_v3")&&migration.includes("qf_vendor_review_decision_audit_v3"));
check("no false external success state",!queue.includes("Google verified successfully")&&!queue.includes("provider delivered"));
console.log("VENDOR_ADMIN_APPROVAL_V3_SOURCE_PASS "+count+"/"+count);
